function addButton(parent,title,fn) { const b=n('button',title,{type:'button'}); b.addEventListener('click',fn); parent.append(b); return b; }
function appendText(parent,label,value) { parent.append(n('p',`${label}: ${value ?? 'Unavailable'}`)); }
function refs(s) { if (!s.trim()) return []; return lines(s).map(row=>{ const i=row.lastIndexOf(':'); const id=row.slice(0,i), revision=Number(row.slice(i+1)); if(i<1 || !Number.isInteger(revision) || revision<1) throw Error('Use one exact contribution ID:revision per line.'); return {id,revision}; }); }
function listValid(x, empty=false) { return (empty || x.length>0) && x.length<=20 && x.every(s=>s.length<=4000) && new Set(x).size===x.length; }

