   const selectedFrom=compareFrom.value,selectedTo=compareTo.value;for(const select of [compareFrom,compareTo]){select.replaceChildren();for(const v of versions)select.append(n('option',`Version ${v.version}`,{value:v.version}));}if(versions.length>1){compareFrom.value=versions.some(v=>String(v.version)===selectedFrom)?selectedFrom:String(versions[0].version);compareTo.value=versions.some(v=>String(v.version)===selectedTo)&&selectedTo!==compareFrom.value?selectedTo:String(versions[versions.length-1].version);compareButton.disabled=compareFrom.value===compareTo.value;}else compareButton.disabled=true;for(const v of versions) rowVersion(historyList,v);
